message.content:
{
  "personality": {
    "traits": ["守时重诺", "寡言务实", "对生人存三分戒心"],
    "values": ["行会规矩是活路", "家人安稳胜过远利"],
    "flaws": ["遇争执常先退让，事后才懊恼"
    ]
  },
  "voice": {
    "register": "市井白话，夹杂行会行话，语速偏慢",
    "accent": "河埠一带水路口音，尾音略拖",
    "habits": ["说话前先清一下嗓子", "算数时手指在膝上轻点"],
    "samples": [
      "船到埠头先系缆，账后头再算，急不得。",
      "行会里的事，我照章程报，不替谁多添一句。",
      "白生，今日风紧，你收摊莫太晚。"
    ]
  },
  "background": "生在河埠，长在河埠。年轻时跟船跑过几趟短程，后来腿脚不济，便留在埠头替商旅行会做代理。每日点数靠岸货担、记系缆次序、替船家传话，闲时补几段旧缆。与白生搭伙多年，家中大小事由白生操持，他只管外头账目和行会差事。日子过得紧，却也算稳。",
  "currentConcern": "入秋后货船渐密，行会催他多增人手，他一时找不到可靠的人。",
  "goals": [
    "把本季行会账目理清，不出差错",
    "攒些余力，让家中日子松快一点"
  ],
  "fears": [
    "怕自己记性渐差，误了行会的数，也误了船家的货"
  ],
  "knowledge": {
    "unknown": [
      "上游水闸何时开闭的准信",
      "行会东家与外地商帮私下的议价"
    ]
  },
  "relationships": [
    {
      "with": "npc_pop_bs_005_2",
      "relation": "子女",
      "note": "阎和还小，他常抱到埠头看船，教认缆绳结法，话不多，却耐烦。"
    },
    {
      "with": "npc_pop_bs_005_3",
      "relation": "伴侣",
      "note": "白生操持家中饮食起居，他每日收工先寻白生，把当日行会事简略说一遍。"
    }
  ],
  "visibleFeature": "右手虎口有一道旧缆绳磨出的厚茧，左眉尾断了一小截，像是早年磕碰留下的。"
}
